test('object-spread-loose-builtins/side-effect/exec.js [spec, helpers]', async () => {
  const source =
    'var k = { a: 1, b: 2 };\nvar o = { a: 3, ...k, b: k.a++ };\n// Loose will evaluate the static `b: k.a++` before spreading `...k`.\n// It should be {a: 1, b: 1}\nexpect(o).toEqual({a: 2, b: 1});\n\nvar k = { a: 1, get b() { l = { z: 9 }; return 2; } };\nvar l = { c: 3 };\nvar o = { ...k, ...l };\n// Loose will evaluate the `l` before spreading `...k`.\n// It should be {a: 1, b: 2, z: 9}\nexpect(o).toEqual({ a: 1, b: 2, c: 3 });\n';
  expect(
    await transformOutcome(source, 'exec.js', {
      transforms: { objectRestSpread: { loose: false, useBuiltIns: false } },
      helpers: { mode: 'runtime', moduleName: '@babel/runtime', version: '7.29.7' },
    }),
  ).toMatchInlineSnapshot(`
    "var _objectSpread = require('@babel/runtime/helpers/objectSpread2');
    var k = {
      a: 1,
      b: 2,
    };
    var o = _objectSpread(_objectSpread({ a: 3 }, k), {}, { b: k.a++ });
    // Loose will evaluate the static \`b: k.a++\` before spreading \`...k\`.
    // It should be {a: 1, b: 1}
    expect(o).toEqual({
      a: 2,
      b: 1,
    });
    var k = {
      a: 1,
      get b() {
        l = { z: 9 };
        return 2;
      },
    };
    var l = { c: 3 };
    var o = _objectSpread(_objectSpread({}, k), l);
    // Loose will evaluate the \`l\` before spreading \`...k\`.
    // It should be {a: 1, b: 2, z: 9}
    expect(o).toEqual({
      a: 1,
      b: 2,
      c: 3,
    });"
  `);
});

