test('object-spread-loose/no-object-assign-exec/exec.js [spec, helpers]', async () => {
  const source =
    "\"use strict\";\nObject.defineProperty(Object.prototype, 'NOSET', {\n  get(value) {\n    // noop\n  },\n});\n\nObject.defineProperty(Object.prototype, 'NOWRITE', {\n  writable: false,\n  value: 'abc',\n});\n\nconst obj = { 'NOSET': 123 };\n// this won't work as expected if transformed as Object.assign (or equivalent)\n// because those trigger object setters (spread don't)\nexpect(() => {\n  const objSpread = { ...obj };\n}).toThrow();\n\nconst obj2 = { 'NOWRITE': 456 };\n// this throws `TypeError: Cannot assign to read only property 'NOWRITE'`\n// if transformed as Object.assign (or equivalent) because those use *assignment* for creating properties\n// (spread defines them)\nexpect(() => {\n  const obj2Spread = { ...obj2 };\n}).toThrow();\n\nconst KEY = Symbol('key');\nconst obj3Spread = { ...{ get foo () { return 'bar' } }, [KEY]: 'symbol' };\nexpect(Object.getOwnPropertyDescriptor(obj3Spread, 'foo').value).toBe('bar');\nexpect(Object.getOwnPropertyDescriptor(obj3Spread, KEY).value).toBe('symbol');\n\nconst obj4Spread = { ...Object.prototype };\nexpect(Object.getOwnPropertyDescriptor(obj4Spread, 'hasOwnProperty')).toBeUndefined();\n\nexpect(() => ({ ...null, ...undefined })).not.toThrow();\n\nconst o = Object.create(null);\no.a = 'foo';\no.__proto__ = [];\nconst o2 = { ...o };\n// Loose will do o2.__proto__ = []\nexpect(Array.isArray(Object.getPrototypeOf(o2))).toBe(true);\n";
  expect(
    await transformOutcome(source, 'exec.js', {
      transforms: { objectRestSpread: { loose: false, useBuiltIns: false } },
      helpers: { mode: 'runtime', moduleName: '@babel/runtime', version: '7.29.7' },
    }),
  ).toMatchInlineSnapshot(`
    "'use strict';
    var _objectSpread = require('@babel/runtime/helpers/objectSpread2');
    Object.defineProperty(Object.prototype, 'NOSET', {
      get(value) {
        // noop
      },
    });
    Object.defineProperty(Object.prototype, 'NOWRITE', {
      writable: false,
      value: 'abc',
    });
    const obj = { NOSET: 123 };
    // this won't work as expected if transformed as Object.assign (or equivalent)
    // because those trigger object setters (spread don't)
    expect(() => {
      const objSpread = _objectSpread({}, obj);
    }).toThrow();
    const obj2 = { NOWRITE: 456 };
    // this throws \`TypeError: Cannot assign to read only property 'NOWRITE'\`
    // if transformed as Object.assign (or equivalent) because those use *assignment* for creating properties
    // (spread defines them)
    expect(() => {
      const obj2Spread = _objectSpread({}, obj2);
    }).toThrow();
    const KEY = Symbol('key');
    const obj3Spread = _objectSpread(
      _objectSpread(
        {},
        {
          get foo() {
            return 'bar';
          },
        },
      ),
      {},
      { [KEY]: 'symbol' },
    );
    expect(Object.getOwnPropertyDescriptor(obj3Spread, 'foo').value).toBe('bar');
    expect(Object.getOwnPropertyDescriptor(obj3Spread, KEY).value).toBe('symbol');
    const obj4Spread = _objectSpread({}, Object.prototype);
    expect(Object.getOwnPropertyDescriptor(obj4Spread, 'hasOwnProperty')).toBeUndefined();
    expect(() => _objectSpread(_objectSpread({}, null), undefined)).not.toThrow();
    const o = Object.create(null);
    o.a = 'foo';
    o.__proto__ = [];
    const o2 = _objectSpread({}, o);
    // Loose will do o2.__proto__ = []
    expect(Array.isArray(Object.getPrototypeOf(o2))).toBe(true);"
  `);
});

